function validateGoal(goal: string): string {
  if (!goal || typeof goal !== 'string') {
    throw new McpError(ErrorCode.InvalidParams, 'Goal must be a non-empty string');
  }
  const trimmed = goal.trim();
  if (trimmed.length === 0) {
    throw new McpError(ErrorCode.InvalidParams, 'Goal description cannot be empty');
  }
  if (trimmed.length > 500) {
    throw new McpError(ErrorCode.InvalidParams, 'Goal description too long (max 500 characters)');
  }
  return trimmed;
}

function validateTodo(todo: any): void {
  if (!todo.title?.trim()) {
    throw new McpError(ErrorCode.InvalidParams, 'Todo title cannot be empty');
  }
  if (todo.title.length > 200) {
    throw new McpError(ErrorCode.InvalidParams, 'Todo title too long (max 200 characters)');
  }
  if (!todo.description?.trim()) {
    throw new McpError(ErrorCode.InvalidParams, 'Todo description cannot be empty');
  }
  if (todo.description.length > 5000) {
    throw new McpError(ErrorCode.InvalidParams, 'Todo description too long (max 5000 characters)');
  }
  if (typeof todo.complexity !== 'number' || todo.complexity < 0 || todo.complexity > 10) {
    throw new McpError(ErrorCode.InvalidParams, 'Complexity must be a number between 0 and 10');
  }
  if (todo.codeExample && todo.codeExample.length > 10000) {
    throw new McpError(ErrorCode.InvalidParams, 'Code example too long (max 10000 characters)');
  }
}

