export const formatPlanAsTodos = (plan: string): Array<{
  title: string;
  description: string;
  complexity: number;
  codeExample?: string;
  parseWarnings?: string[];
}> => {
  const warnings: string[] = [];
  const sections = plan.split(/\n\s*\n/).filter(s => s.trim().length > 0);

  if (sections.length === 0) {
    warnings.push('Plan appears to be empty or improperly formatted');
  }

  const todos = sections.map((section, index) => {
    const lines = section.split('\n');

    // Try multiple title patterns
    let title = lines[0]
      .replace(/^[0-9]+[\.\)]\s*/, '')  // Numbered: 1. or 1)
      .replace(/^[\-\*\+]\s*/, '')       // Bullets: -, *, +
      .replace(/^#+\s*/, '')              // Headers: ##
      .trim();

    if (!title) {
      title = `Unnamed Task ${index + 1}`;
      warnings.push(`Section ${index + 1} has no clear title`);
    }

    // Try multiple complexity patterns
    const complexityMatches = [
      /Complexity:\s*([0-9]+)/i,
      /\[Complexity:\s*([0-9]+)\]/i,
      /\(complexity:\s*([0-9]+)\)/i,
      /difficulty:\s*([0-9]+)/i
    ];

    let complexity = 5; // default
    for (const pattern of complexityMatches) {
      const match = section.match(pattern);
      if (match) {
        complexity = Math.max(0, Math.min(10, parseInt(match[1])));
        break;
      }
    }

    // Extract code blocks (fenced or indented)
    const fencedCode = section.match(/```[^`]*```/)?.[0];
    const indentedCode = section.match(/(^    .+$\n)+/m)?.[0];
    const codeExample = (fencedCode || indentedCode)?.replace(/^```|```$/g, '').trim();

    // Build description
    let description = section
      .replace(/^[^\n]*\n/, '')  // Remove title line
      .replace(/Complexity:\s*[0-9]+/gi, '')
      .replace(/```[^`]*```/g, '')
      .trim();

    if (!description) {
      description = title;  // Fallback to title if no description
      warnings.push(`Section "${title}" has no description`);
    }

    return {
      title,
      description,
      complexity,
      codeExample,
      parseWarnings: warnings.length > 0 ? [...warnings] : undefined
    };
  });

  return todos;
};

