private saveDebounceTimer: NodeJS.Timeout | null = null;
private readonly SAVE_DEBOUNCE_MS = 1000;  // 1 second

private async save(): Promise<void> {
  // Debounce: accumulate changes and save after delay
  if (this.saveDebounceTimer) {
    clearTimeout(this.saveDebounceTimer);
  }

  this.saveDebounceTimer = setTimeout(async () => {
    try {
      await fs.writeFile(this.storagePath, JSON.stringify(this.data, null, 2));
      this.saveDebounceTimer = null;
    } catch (error: any) {
      console.error('[Storage] Save failed:', error.message);
      throw new Error(`Storage save failed: ${error.message}`);
    }
  }, this.SAVE_DEBOUNCE_MS);
}

async flush(): Promise<void> {
  // Force immediate save (e.g., on shutdown)
  if (this.saveDebounceTimer) {
    clearTimeout(this.saveDebounceTimer);
  }
  await fs.writeFile(this.storagePath, JSON.stringify(this.data, null, 2));
}

