// Pre-compile regex patterns
const COMPLEXITY_PATTERN = /Complexity:\s*([0-9]+)/;
const CODE_BLOCK_PATTERN = /```[^`]*```/;
const NUMBERED_LIST = /^[0-9]+[\.\)]\s*/;

export const formatPlanAsTodos = (plan: string): Array<...> => {
  // Single pass parsing instead of multiple regex operations
  const sections = plan.split('\n\n').filter(s => s.trim().length > 0);

  return sections.map(section => {
    const lines = section.split('\n');
    const title = lines[0].replace(NUMBERED_LIST, '').trim();

    // Single pass through section text
    let complexity = 5;
    let codeExample: string | undefined;

    const complexityMatch = COMPLEXITY_PATTERN.exec(section);
    if (complexityMatch) {
      complexity = parseInt(complexityMatch[1]);
    }

    const codeMatch = CODE_BLOCK_PATTERN.exec(section);
    if (codeMatch) {
      codeExample = codeMatch[0].replace(/^```|```$/g, '');
    }

    const description = section
      .replace(lines[0], '')
      .replace(COMPLEXITY_PATTERN, '')
      .replace(CODE_BLOCK_PATTERN, '')
      .trim();

    return { title, description, complexity, codeExample };
  });
};

// Simple token bucket rate limiter
class RateLimiter {
  private tokens: number;
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private lastRefill: number;

  constructor(maxTokens: number, refillPerSecond: number) {
    this.maxTokens = maxTokens;
    this.tokens = maxTokens;
    this.refillRate = refillPerSecond;
    this.lastRefill = Date.now();
  }

  consume(): boolean {
    this.refill();
    if (this.tokens >= 1) {
      this.tokens -= 1;
      return true;
    }
    return false;
  }

  private refill(): void {
    const now = Date.now();
    const elapsed = (now - this.lastRefill) / 1000;
    this.tokens = Math.min(this.maxTokens, this.tokens + elapsed * this.refillRate);
    this.lastRefill = now;
  }
}

